(6433734, 954487, 30669, '<td valign="top">What a very interesting place.</td>', 'What a very interesting place.', '2011-06-04 09:36:30.000000', NULL, 1),
(6433762, 954047, 115676, '<td valign="top">would have scored better without the food in his mouth.</td>', 'would have scored better without the food in his mouth.', '2011-06-04 09:54:14.000000', NULL, 1),
(6433764, 954446, 115676, '<td valign="top">I can''t tell what I am looking at.</td>', 'I can''t tell what I am looking at.', '2011-06-04 09:55:37.000000', NULL, 1),
