(6433836, 954445, 76335, '<td valign="top">Great scene but too much Topaz (or something) for me.</td>', 'Great scene but too much Topaz (or something) for me.', '2011-06-04 11:35:11.000000', NULL, 1),
(6433837, 951712, 76335, '<td valign="top">Processing is overdone.</td>', 'Processing is overdone.', '2011-06-04 11:35:21.000000', NULL, 1),
