(6433843, 954442, 76335, '<td valign="top">Great scene. Too much processing though.</td>', 'Great scene. Too much processing though.', '2011-06-04 11:42:40.000000', NULL, 1),
(6433844, 954140, 124815, '<td valign="top">Just like a shot from the early Italian cinema.</td>', 'Just like a shot from the early Italian cinema.', '2011-06-04 11:43:15.000000', NULL, 1),
