(6433848, 954383, 76335, '<td valign="top">I have to wonder what''s interesting about the people''s backs here. Also, the crop is a bit too tight at the feet.</td>', 'I have to wonder what''s interesting about the people''s backs here. Also, the crop is a bit too tight at the feet.', '2011-06-04 11:43:53.000000', NULL, 1),
(6433849, 954689, 76335, '<td valign="top">Beautiful brushstrokes.</td>', 'Beautiful brushstrokes.', '2011-06-04 11:44:24.000000', NULL, 1),
(6433850, 950820, 76335, '<td valign="top">A wonderfully quirky composition. Only wish the dog''s face were better lit -- I missed him at first.</td>', 'A wonderfully quirky composition. Only wish the dog''s face were better lit -- I missed him at first.', '2011-06-04 11:45:48.000000', NULL, 1),
(6433852, 953740, 76335, '<td valign="top">I love the rhythm of this -- like a parade. These are becoming a cliche, but I''m still a sucker for them.</td>', 'I love the rhythm of this -- like a parade. These are becoming a cliche, but I''m still a sucker for them.', '2011-06-04 11:48:00.000000', NULL, 1),
(6433854, 953192, 76335, '<td valign="top">Nice bold colors and a simple byt very effect composition. My only quibble is the color shift in the red that don''t feel quite right.</td>', 'Nice bold colors and a simple byt very effect composition. My only quibble is the color shift in the red that don''t feel quite right.', '2011-06-04 11:58:26.000000', NULL, 1),
(6433910, 950313, 60047, '<td valign="top">Reminds me of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=83313" rel="nofollow" target="_blank">Yo_Spiff</a>. Great detail.</td>', 'Reminds me of  Yo_Spiff. Great detail.', '2011-06-04 14:05:16.000000', NULL, 1),
(6433922, 953740, 83313, '<td valign="top">Very cool looking. Usually this sort of blur I see done in strong colors, but the b/w looks wonderful.</td>', 'Very cool looking. Usually this sort of blur I see done in strong colors, but the b/w looks wonderful.', '2011-06-04 14:22:37.000000', NULL, 1),
(6433931, 954173, 76335, '<td valign="top">This is a fabulous composition. It''s busy and noisy and full of life, but there''s not a pulse or a hearbeat to be found.</td>', 'This is a fabulous composition. It''s busy and noisy and full of life, but there''s not a pulse or a hearbeat to be found.', '2011-06-04 14:39:01.000000', NULL, 1),
(6433933, 954665, 76335, '<td valign="top">I love how you balanced the stony monolith against the distant, seemingly delicate, boat.</td>', 'I love how you balanced the stony monolith against the distant, seemingly delicate, boat.', '2011-06-04 14:39:41.000000', NULL, 1),
(6433934, 953957, 76335, '<td valign="top">The sky is totally overworked in post. I think you could have done a red channel black and white conversion, added some contrast, and called it done.</td>', 'The sky is totally overworked in post. I think you could have done a red channel black and white conversion, added some contrast, and called it done.', '2011-06-04 14:40:46.000000', NULL, 1),
(6433935, 954507, 76335, '<td valign="top">Great photo. But not with a ten foot pole, Sweetie. Seven.</td>', 'Great photo. But not with a ten foot pole, Sweetie. Seven.', '2011-06-04 14:41:50.000000', NULL, 1),
(6433937, 954633, 76335, '<td valign="top">Feels voyeuristic.</td>', 'Feels voyeuristic.', '2011-06-04 14:42:29.000000', NULL, 1),
(6433938, 954673, 76335, '<td valign="top">I''m feeling <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=41746" rel="nofollow" target="_blank">gsal</a> vibes here. The feeling of your subject letting his gaurd down -- but just a little -- is magnificent.</td>', 'I''m feeling  gsal vibes here. The feeling of your subject letting his gaurd down -- but just a little -- is magnificent.', '2011-06-04 14:44:24.000000', NULL, 1),
(6433939, 954204, 76335, '<td valign="top">The textures in the hair and skin are smeared. Very unflattering.</td>', 'The textures in the hair and skin are smeared. Very unflattering.', '2011-06-04 14:45:36.000000', NULL, 1),
(6433940, 953989, 76335, '<td valign="top">I love natural light, soft focus, and candid moments like this. I think black and white would have been an improvement, as the color doesn''t add much. Also, an angle that shows more face and less window frame would have been better.</td>', 'I love natural light, soft focus, and candid moments like this. I think black and white would have been an improvement, as the color doesn''t add much. Also, an angle that shows more face and less window frame would have been better.', '2011-06-04 14:47:23.000000', NULL, 1),
(6433942, 954499, 76335, '<td valign="top">I like the way the sun burns your subject into the frame. Well composed. Excellent.</td>', 'I like the way the sun burns your subject into the frame. Well composed. Excellent.', '2011-06-04 14:48:15.000000', NULL, 1),
(6433945, 952294, 76335, '<td valign="top">This is too weird not to like. And totally beyond critique, because it''s hard to believe you were going after something and missed by such a wide margin that you got this instead. A unique vision, then. A winner.</td>', 'This is too weird not to like. And totally beyond critique, because it''s hard to believe you were going after something and missed by such a wide margin that you got this instead. A unique vision, then. A winner.', '2011-06-04 14:50:47.000000', NULL, 1),
(6433946, 953471, 76335, '<td valign="top">Strange and interesting bokeh. Great tones.</td>', 'Strange and interesting bokeh. Great tones.', '2011-06-04 14:51:02.000000', NULL, 1),
(6433976, 954443, 76335, '<td valign="top">A refreshingly different sort of landscape. Beautiful layers and nice touches here and there (birds, a few discrete trees...)</td>', 'A refreshingly different sort of landscape. Beautiful layers and nice touches here and there (birds, a few discrete trees...)', '2011-06-04 16:31:26.000000', NULL, 1),
(6433977, 954244, 76335, '<td valign="top">This has <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=100831" rel="nofollow" target="_blank">PennyStreet</a> written all over it. The repeeating theme reveals, upon closer inspection, something a little different in each compartment. Excellent.</td>', 'This has  PennyStreet written all over it. The repeeating theme reveals, upon closer inspection, something a little different in each compartment. Excellent.', '2011-06-04 16:32:57.000000', NULL, 1),
(6433978, 953890, 76335, '<td valign="top">Wonderful textures all around.</td>', 'Wonderful textures all around.', '2011-06-04 16:33:31.000000', NULL, 1),
(6433979, 952769, 76335, '<td valign="top">Good use of thirds. And I love the magical landscape that he inhabits.</td>', 'Good use of thirds. And I love the magical landscape that he inhabits.', '2011-06-04 16:34:00.000000', NULL, 1),
(6433980, 951824, 76335, '<td valign="top">A still life that isn''t. Interesting juxtaposition.</td>', 'A still life that isn''t. Interesting juxtaposition.', '2011-06-04 16:34:37.000000', NULL, 1),
(6433983, 952509, 124815, '<td valign="top">Exceptional!</td>', 'Exceptional!', '2011-06-04 16:36:13.000000', NULL, 1),
