(6437880, 954714, 68504, '<td valign="top">Love the light colours, and how they seem to allow the textures to be one grand texture.</td>', 'Love the light colours, and how they seem to allow the textures to be one grand texture.', '2011-06-08 02:08:01.000000', NULL, 0),
(6437881, 953722, 96751, '<td valign="top">Very unique and worth of its top 10 finish.  Congrats!</td>', 'Very unique and worth of its top 10 finish.  Congrats!', '2011-06-08 02:08:06.000000', NULL, 0),
(6437882, 954114, 96751, '<td valign="top">Well, you''ve certainly figured out what DPC likes :-)</td>', 'Well, you''ve certainly figured out what DPC likes :-)', '2011-06-08 02:08:58.000000', NULL, 0),
