(6437888, 950372, 68504, '<td valign="top">take a moment.</td>', 'take a moment.', '2011-06-08 02:12:13.000000', NULL, 0),
(6437889, 954625, 30982, '<td valign="top">This was high on my list - I wanted to just wander on down that road. Very inviting!  Great title, too.</td>', 'This was high on my list - I wanted to just wander on down that road. Very inviting!  Great title, too.', '2011-06-08 02:12:34.000000', NULL, 0),
(6437890, 951622, 30982, '<td valign="top">She seemed so happy...</td>', 'She seemed so happy...', '2011-06-08 02:13:48.000000', NULL, 0),
(6437894, 954720, 30982, '<td valign="top">A most excellent perspective!  Woefully underappreciated.</td>', 'A most excellent perspective!  Woefully underappreciated.', '2011-06-08 02:14:55.000000', NULL, 0),
(6437895, 954431, 113156, '<td valign="top">One of my favorites in this challenge, a really great photo and your processing was spot on.</td>', 'One of my favorites in this challenge, a really great photo and your processing was spot on.', '2011-06-08 02:15:05.000000', NULL, 0),
(6437897, 954803, 30982, '<td valign="top">What an excellent title for this!  And what a remarkable comment from <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=97225" rel="nofollow" target="_blank">jomari</a>.</td>', 'What an excellent title for this!  And what a remarkable comment from  jomari.', '2011-06-08 02:16:02.000000', NULL, 0),
(6437900, 954620, 30982, '<td valign="top">What''s this doing way down here??  Love the inked watercolor of the lamppost.</td>', 'What''s this doing way down here??  Love the inked watercolor of the lamppost.', '2011-06-08 02:17:05.000000', NULL, 0),
(6437903, 954248, 30982, '<td valign="top">The photograph appears a bit blotchy to me, though that may be your choice of processing, but it definitely speaks of loneliness.  Well seen.</td>', 'The photograph appears a bit blotchy to me, though that may be your choice of processing, but it definitely speaks of loneliness.  Well seen.', '2011-06-08 02:18:42.000000', NULL, 0),
(6437904, 954763, 30982, '<td valign="top">I don''t think she''s all that pleased with you...  I like this one, but I like your other stripes better.  And how dare you let Tom shoot warped and reflected windows?  Could cause all sorts of chaos, you know...</td>', 'I don''t think she''s all that pleased with you...  I like this one, but I like your other stripes better.  And how dare you let Tom shoot warped and reflected windows?  Could cause all sorts of chaos, you know...', '2011-06-08 02:20:07.000000', NULL, 0),
(6437906, 954579, 30982, '<td valign="top">LOL about the guano!  That is an occupational hazard of shooting birds.  Nice sense of quiet here.</td>', 'LOL about the guano!  That is an occupational hazard of shooting birds.  Nice sense of quiet here.', '2011-06-08 02:21:01.000000', NULL, 0),
(6437907, 954600, 30982, '<td valign="top">And a marvelous minimal landscape it is, too.  The texture on the water is nearly hypnotic.</td>', 'And a marvelous minimal landscape it is, too.  The texture on the water is nearly hypnotic.', '2011-06-08 02:22:20.000000', NULL, 0),
(6437909, 950372, 30982, '<td valign="top">An amazing trifecta.</td>', 'An amazing trifecta.', '2011-06-08 02:24:37.000000', NULL, 0),
(6437911, 954787, 30982, '<td valign="top">A starlet, she is.  Posing center stage and holding that leg just so!</td>', 'A starlet, she is.  Posing center stage and holding that leg just so!', '2011-06-08 02:26:07.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6437912, 954448, 97225, '<td valign="top">This is beautiful - it was in my top handful.</td>', 'This is beautiful - it was in my top handful.', '2011-06-08 02:29:44.000000', NULL, 0),
(6437914, 953953, 30214, '<td valign="top">beautiful photo, fitting the blue ribbon. congratulations!</td>', 'beautiful photo, fitting the blue ribbon. congratulations!', '2011-06-08 02:33:07.000000', NULL, 0),
(6437916, 954689, 93565, '<td valign="top">Hmm... I think this got voted a bit lower than it deserved, Tome. It''s a very nice floral shot. While it doesn''t have the POW! effect of many that do well on here, it is the subdued nature itself that makes this appealing. The (overall) muted colors and nice use of DoF combine nicely.</td>', 'Hmm... I think this got voted a bit lower than it deserved, Tome. It''s a very nice floral shot. While it doesn''t have the POW! effect of many that do well on here, it is the subdued nature itself that makes this appealing. The (overall) muted colors and nice use of DoF combine nicely.', '2011-06-08 02:34:12.000000', NULL, 0),
(6437921, 954262, 93565, '<td valign="top">Wow... the creamy bokeh alongside those crazy circles of confusion is wonderful. A very simple scene, and a well established DPC cliche with the drops, but done in a different and refreshing fashion. Exudes warm summer nights for me.</td>', 'Wow... the creamy bokeh alongside those crazy circles of confusion is wonderful. A very simple scene, and a well established DPC cliche with the drops, but done in a different and refreshing fashion. Exudes warm summer nights for me.', '2011-06-08 02:38:04.000000', NULL, 0),
(6437923, 953117, 97225, '<td valign="top">It appealed to me. I was one of your 8s.</td>', 'It appealed to me. I was one of your 8s.', '2011-06-08 02:38:19.000000', NULL, 0),
(6437929, 954698, 30214, '<td valign="top">Hey Nick! so glad to see you back!!! setting fire again? your eye is as sharp as ever<br/><br/><i>Message edited by author 2011-06-08 01:41:55.</i></td>', 'Hey Nick! so glad to see you back!!! setting fire again? your eye is as sharp as ever', '2011-06-08 02:40:50.000000', '2011-06-08 02:41:55.000000', 0),
(6437931, 954825, 19959, '<td valign="top">congrats on the Ribbon... this is a spectacular image. <br/></td>', 'congrats on the Ribbon... this is a spectacular image. ', '2011-06-08 02:41:05.000000', NULL, 0),
(6437941, 954664, 91783, '<td valign="top">very very very under-rated!! i loved this one and gave it a 9!</td>', 'very very very under-rated!! i loved this one and gave it a 9!', '2011-06-08 02:43:22.000000', NULL, 0),
(6437949, 954669, 93565, '<td valign="top">I like your composition with the waterway, but the fence just seems odd and out of place, incidental. It''s hanging there, not doing anything, which hurts the strength of the waterway. This is sorta magnified a bit by the nature of the fence- it''s angular, and hard edged, while the rest of the scene is more organic, with curves and softness.<br/>An interesting aspect of this photo is that the sky, though much larger, doesn''t really steal the show... it feels about equal in strength to the foliage/waterway.</td>', 'I like your composition with the waterway, but the fence just seems odd and out of place, incidental. It''s hanging there, not doing anything, which hurts the strength of the waterway. This is sorta magnified a bit by the nature of the fence- it''s angular, and hard edged, while the rest of the scene is more organic, with curves and softness.An interesting aspect of this photo is that the sky, though much larger, doesn''t really steal the show... it feels about equal in strength to the foliage/waterway.', '2011-06-08 02:46:41.000000', NULL, 0),
(6437951, 953656, 97225, '<td valign="top">It''s been some years since I visited this spot (thought it was called Natural Arch) but it sticks in my mind as one of the best locations I''ve ever been to. You''ve done a wonderful job with the HDR to bring out the colours and tonal range.</td>', 'It''s been some years since I visited this spot (thought it was called Natural Arch) but it sticks in my mind as one of the best locations I''ve ever been to. You''ve done a wonderful job with the HDR to bring out the colours and tonal range.', '2011-06-08 02:47:39.000000', NULL, 0),
(6437954, 953828, 108580, '<td valign="top">BiF photography is incredibly difficult and technical. Yes you can hold the shutter down and fire away but in most cases this rarely even gets one good shot. I''m surprised it didn''t do better. No wait, it''s not a DPC landscape! :) Keep up the great work.</td>', 'BiF photography is incredibly difficult and technical. Yes you can hold the shutter down and fire away but in most cases this rarely even gets one good shot. I''m surprised it didn''t do better. No wait, it''s not a DPC landscape! :) Keep up the great work.', '2011-06-08 02:49:19.000000', NULL, 0),
(6437957, 954588, 97225, '<td valign="top">Love this.</td>', 'Love this.', '2011-06-08 02:50:48.000000', NULL, 0),
(6437958, 953953, 59267, '<td valign="top">Wow! Yosemite covered by snow at this season! that''s unusual indeed. Very beautiful foggy morning. Congratulations on your blue and excellent capture!</td>', 'Wow! Yosemite covered by snow at this season! that''s unusual indeed. Very beautiful foggy morning. Congratulations on your blue and excellent capture!', '2011-06-08 02:51:09.000000', NULL, 0),
(6437959, 954047, 91783, '<td valign="top">LOL i knew this was yours! nice job over all! lighting seems even and clearity is really nice! too bad it didn''t score a bit better. (i do have to agree with the food though...)</td>', 'LOL i knew this was yours! nice job over all! lighting seems even and clearity is really nice! too bad it didn''t score a bit better. (i do have to agree with the food though...)', '2011-06-08 02:51:28.000000', NULL, 0),
(6437961, 953931, 91783, '<td valign="top">the tires do look a little too new, but over all a really great image! the post processing is excellent! nice colors and tones!</td>', 'the tires do look a little too new, but over all a really great image! the post processing is excellent! nice colors and tones!', '2011-06-08 02:53:16.000000', NULL, 0),
(6437962, 954443, 54645, '<td valign="top">Great to see you back. I saw this and was impressed that the photographer conjured an emotive landscape, anchored in geometry and tones, that very few can create; it made me wonder what Z was doing. What a pleasant surprise! A stunning piece of work.</td>', 'Great to see you back. I saw this and was impressed that the photographer conjured an emotive landscape, anchored in geometry and tones, that very few can create; it made me wonder what Z was doing. What a pleasant surprise! A stunning piece of work.', '2011-06-08 02:56:21.000000', NULL, 0),
(6437966, 953100, 97225, '<td valign="top">Wow! I gave you a 9 for this lovely scene and I''m sorry I didn''t leave a comment at the time. I can''t believe it didn''t finish a lot higher.</td>', 'Wow! I gave you a 9 for this lovely scene and I''m sorry I didn''t leave a comment at the time. I can''t believe it didn''t finish a lot higher.', '2011-06-08 03:00:01.000000', NULL, 0),
(6437967, 954547, 102534, '<td valign="top">Awesome shot, all the more so considering you took it with your iPhone. Congratulations on finishing in the top 10 in a free study!</td>', 'Awesome shot, all the more so considering you took it with your iPhone. Congratulations on finishing in the top 10 in a free study!', '2011-06-08 03:02:40.000000', NULL, 0),
(6437969, 954431, 68504, '<td valign="top">Modern baroque. Very well presented.</td>', 'Modern baroque. Very well presented.', '2011-06-08 03:05:01.000000', NULL, 0),
(6437971, 954547, 102519, '<td valign="top">Very Nice Mr. A congratulations</td>', 'Very Nice Mr. A congratulations', '2011-06-08 03:07:21.000000', NULL, 0),
(6437972, 954547, 8759, '<td valign="top">Awesome! Top 10 in a free study with iPhone!</td>', 'Awesome! Top 10 in a free study with iPhone!', '2011-06-08 03:07:47.000000', NULL, 0),
(6437974, 953953, 108580, '<td valign="top">Fantastic work wd.</td>', 'Fantastic work wd.', '2011-06-08 03:10:04.000000', NULL, 0),
(6437975, 954543, 54645, '<td valign="top">Another excellent scene, full of the quiet moments of life.</td>', 'Another excellent scene, full of the quiet moments of life.', '2011-06-08 03:11:03.000000', NULL, 0),
(6437976, 954825, 108580, '<td valign="top">Hope the little guys isn''t red underneath from all the belly flops.<br/>Love that he appears to look at the drop. Congrats.</td>', 'Hope the little guys isn''t red underneath from all the belly flops.Love that he appears to look at the drop. Congrats.', '2011-06-08 03:12:58.000000', NULL, 0),
(6437977, 954065, 108580, '<td valign="top">WD on the yellow!</td>', 'WD on the yellow!', '2011-06-08 03:14:40.000000', NULL, 0),
(6437983, 953704, 108580, '<td valign="top">WD on a very technical image in all dept''s.</td>', 'WD on a very technical image in all dept''s.', '2011-06-08 03:18:02.000000', NULL, 0),
(6437985, 954680, 86218, '<td valign="top">Stunner. Baie mooi Marna. Daai finger van jou was in sync met die voel se brein verseker. Alles gevries. Baie voel fotograwe sal se hul wil bietjie beweging sien in die vlerke etc etc etc.. Ek hou baie hiervan en in ''n FS het jy uitstekend gevaar. Net jammer dit is nie in die top 10 nie want ek voel dit moes gewees het. Enigste klein nit is die tak agter wat skynbaar ingaan by die voel. Dit is egter die wonder en frustrasie van natuurlike oomblikke.</td>', 'Stunner. Baie mooi Marna. Daai finger van jou was in sync met die voel se brein verseker. Alles gevries. Baie voel fotograwe sal se hul wil bietjie beweging sien in die vlerke etc etc etc.. Ek hou baie hiervan en in ''n FS het jy uitstekend gevaar. Net jammer dit is nie in die top 10 nie want ek voel dit moes gewees het. Enigste klein nit is die tak agter wat skynbaar ingaan by die voel. Dit is egter die wonder en frustrasie van natuurlike oomblikke.', '2011-06-08 03:18:45.000000', NULL, 0),
(6437986, 954543, 108580, '<td valign="top">Gotcha John :) Wd on HM</td>', 'Gotcha John :) Wd on HM', '2011-06-08 03:19:20.000000', NULL, 0),
(6437988, 953960, 108580, '<td valign="top">Super work, wd on top10 in a FS.</td>', 'Super work, wd on top10 in a FS.', '2011-06-08 03:20:18.000000', NULL, 0),
(6437989, 954698, 54645, '<td valign="top">Wow. Completely missed this image, I''m glad Lev posted it in the PH thread. Well done.</td>', 'Wow. Completely missed this image, I''m glad Lev posted it in the PH thread. Well done.', '2011-06-08 03:20:53.000000', NULL, 0),
(6437990, 954809, 108580, '<td valign="top">Kudo''s on your FS Top10. Well deserved.</td>', 'Kudo''s on your FS Top10. Well deserved.', '2011-06-08 03:22:20.000000', NULL, 0),
(6437991, 953722, 108580, '<td valign="top">Super work with an Ultra Wide Angle, this is how to use them without pincushion or barrel distortion! ''grats on FS Top10.</td>', 'Super work with an Ultra Wide Angle, this is how to use them without pincushion or barrel distortion! ''grats on FS Top10.', '2011-06-08 03:24:15.000000', NULL, 0),
(6437993, 954443, 93565, '<td valign="top">This is gorgeous. The birds, though subdued, add a great deal to the character of the scene. Thoroughly appreciated.</td>', 'This is gorgeous. The birds, though subdued, add a great deal to the character of the scene. Thoroughly appreciated.', '2011-06-08 03:25:23.000000', NULL, 0),
(6437994, 954443, 113591, '<td valign="top">Serene. Thank you.</td>', 'Serene. Thank you.', '2011-06-08 03:25:46.000000', NULL, 0),
(6437997, 954777, 108580, '<td valign="top">Scott, I''m amazed you only got one comment, mine! But I love BiF work. I entered a wildlife shot too, and as expected it didn''t fare too well in landscape mad DPC. How many shots did you take or was this a one off hand crafted image?</td>', 'Scott, I''m amazed you only got one comment, mine! But I love BiF work. I entered a wildlife shot too, and as expected it didn''t fare too well in landscape mad DPC. How many shots did you take or was this a one off hand crafted image?', '2011-06-08 03:29:00.000000', NULL, 0),
(6437999, 954547, 86218, '<td valign="top">Top 10 Anthony! Great score in a free study and an even greater pic. Im sucked in by this shot</td>', 'Top 10 Anthony! Great score in a free study and an even greater pic. Im sucked in by this shot', '2011-06-08 03:29:17.000000', NULL, 0),
(6438000, 954547, 109341, '<td valign="top">Well done boss!  Top 10 with an iPhone shot would be impressive in any challenge, in a Free Study...it''s just outstanding!  Congrats again!</td>', 'Well done boss!  Top 10 with an iPhone shot would be impressive in any challenge, in a Free Study...it''s just outstanding!  Congrats again!', '2011-06-08 03:37:59.000000', NULL, 0),
