INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6439051, 954619, 68956, '<td valign="top">Strangely engaging :)</td>', 'Strangely engaging :)', '2011-06-08 19:02:20.000000', NULL, 0),
(6439076, 953117, 108069, '<td valign="top">Sorry man, but I would have given it a five. I love an abstract, and this is quite nice with the depth and pulsing motion, but there''s a great deal to it that has me wondering if someone just hasn''t gone haywire on the sliders. There''s enough smooth gradation to make me think it''s not just knob twiddling for twiddling sake, but there isn''t enough of a feel to the image to convince me the photographer has any connection, or that I should spend time to find a connection. Right about middle is how I see it as presented on its own.<br/> <br/>Interestingly, one of the things I do not like about it is the color. It''s just a bit jarring to me, and I prefer my abstracts more subtle, almost mysterious. I bet if you''d gone grey tones you''d get a lot more love its.</td>', 'Sorry man, but I would have given it a five. I love an abstract, and this is quite nice with the depth and pulsing motion, but there''s a great deal to it that has me wondering if someone just hasn''t gone haywire on the sliders. There''s enough smooth gradation to make me think it''s not just knob twiddling for twiddling sake, but there isn''t enough of a feel to the image to convince me the photographer has any connection, or that I should spend time to find a connection. Right about middle is how I see it as presented on its own. Interestingly, one of the things I do not like about it is the color. It''s just a bit jarring to me, and I prefer my abstracts more subtle, almost mysterious. I bet if you''d gone grey tones you''d get a lot more love its.', '2011-06-08 19:21:50.000000', NULL, 0),
(6439099, 952684, 124815, '<td valign="top">You chose well this image over the outtake. Powerful and ruthless.</td>', 'You chose well this image over the outtake. Powerful and ruthless.', '2011-06-08 19:59:37.000000', NULL, 0),
(6439103, 953117, 102278, '<td valign="top">Yes, we must have swopped bodies. Enjoy the nightmares dude!<br/> <br/>Cool abstract though! Looks like a sunspot. I like it! (also, cheers for pointing out the Dragon/Damsel fly thing. I didn''t know the difference.</td>', 'Yes, we must have swopped bodies. Enjoy the nightmares dude! Cool abstract though! Looks like a sunspot. I like it! (also, cheers for pointing out the Dragon/Damsel fly thing. I didn''t know the difference.', '2011-06-08 20:11:12.000000', NULL, 0),
(6439114, 953900, 69325, '<td valign="top">I think maybe because its such a static pose perhaps? I can''t quite put my finger on it, perhaps not filling the frame with his face might have been more effective. I do like the color but b&amp;w may have been more effective in conveying your title.</td>', 'I think maybe because its such a static pose perhaps? I can''t quite put my finger on it, perhaps not filling the frame with his face might have been more effective. I do like the color but b&w may have been more effective in conveying your title.', '2011-06-08 20:19:41.000000', NULL, 0),
(6439116, 953953, 103142, '<td valign="top">Absolutely gorgeous!! What an incredible shot! Congrats on the blue. :D</td>', 'Absolutely gorgeous!! What an incredible shot! Congrats on the blue. :D', '2011-06-08 20:24:45.000000', NULL, 0),
(6439133, 954825, 15711, '<td valign="top">So rarely do I hand out tens.  This got one with no hesitation.  Just FABULOUS!!!!!!</td>', 'So rarely do I hand out tens.  This got one with no hesitation.  Just FABULOUS!!!!!!', '2011-06-08 20:48:15.000000', NULL, 0),
(6439134, 950372, 76335, '<td valign="top">Thanks for daring. Again.</td>', 'Thanks for daring. Again.', '2011-06-08 20:52:09.000000', NULL, 0),
(6439135, 953957, 132021, '<td valign="top">There''s a debate I''m not going to get into. But thanks for stopping by and taking the time to comment!</td>', 'There''s a debate I''m not going to get into. But thanks for stopping by and taking the time to comment!', '2011-06-08 20:52:45.000000', NULL, 0),
(6439136, 954825, 98339, '<td valign="top">Well, look at you!!!  Great job!!!</td>', 'Well, look at you!!!  Great job!!!', '2011-06-08 20:52:51.000000', NULL, 0),
(6439141, 954620, 76335, '<td valign="top">For all your commenting efforts, it''s sad that this didn''t get a single comment during voting. I gave it a six, which was probably kind of stingy. My comment would have been along the lines of your composition. The layers seem to suggest a procession -- or something else that has more to do with time than space. There''s a poem here. I should have taken more time to read it...</td>', 'For all your commenting efforts, it''s sad that this didn''t get a single comment during voting. I gave it a six, which was probably kind of stingy. My comment would have been along the lines of your composition. The layers seem to suggest a procession -- or something else that has more to do with time than space. There''s a poem here. I should have taken more time to read it...', '2011-06-08 21:04:46.000000', NULL, 0),
(6439143, 953131, 76335, '<td valign="top">I gave it a seven. It''s a quirky composition, which isn''t going to (and didn''t) appeal to everyone. But I appreciated the effort, and have a feeling you got exactly the picture you wanted. <br/> <br/>If the voters didn''t connect, the problem is their own. This is beautifully done. Remember -- WOW burns fast.</td>', 'I gave it a seven. It''s a quirky composition, which isn''t going to (and didn''t) appeal to everyone. But I appreciated the effort, and have a feeling you got exactly the picture you wanted.  If the voters didn''t connect, the problem is their own. This is beautifully done. Remember -- WOW burns fast.', '2011-06-08 21:07:32.000000', NULL, 0),
(6439144, 954723, 76335, '<td valign="top">Love the motion, the energy here. Great work, crik!</td>', 'Love the motion, the energy here. Great work, crik!', '2011-06-08 21:11:04.000000', NULL, 0),
(6439145, 954817, 76335, '<td valign="top">Of course this belongs to you. I stared at it for a while, but any words I typed sounded stupid. Kind of like these... <br/> <br/>Seven from me.</td>', 'Of course this belongs to you. I stared at it for a while, but any words I typed sounded stupid. Kind of like these...  Seven from me.', '2011-06-08 21:12:09.000000', NULL, 0),
